"use client";

import type { ChartRoot } from "./chart-utils";
import { useMergedRef } from "../lib/form";
import {
  useCallback,
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent,
  type PointerEvent,
  type ReactNode,
} from "react";

import { cn } from "../lib/cn";
import { useSyncRef } from "../hooks/use-latest";
import { useSheenReducedMotion } from "../hooks/use-preferences";
import { ChartAnnouncer, ChartEmpty } from "./chart-parts";
import { dockSpace, type Readout, useDockedReadout } from "./chart-fit";
import { chartFocusClass, clamp, useElementWidth, resolveInstructions } from "./chart-utils";
import {
  ChartDockHint,
  defaultCompact,
  defaultPercent,
  useEntrance,
  useScrollFade,
  type ChartTipAnchor,
} from "./heatmap";
import {
  FlowTip,
  haloTextClass,
  markGlow,
  measureText,
  fitText,
  r2,
  roundedRectPath,
  useDarkScheme,
  useFontsLoaded,
  useFrameStore,
  wrapText,
} from "./flow-utils";

import { type SankeyLayoutLink, type SankeyLayoutNode, layoutSankey, byY } from "./sankey-chart/layout";
import { useSankeyStaticLayers } from "./sankey-chart/layers";
import { useSankeyPaint } from "./sankey-chart/use-sankey-paint";
import { sankeyLinkReadout, sankeyNodeReadout } from "./sankey-chart/readout";
import { placeSankeyLabels } from "./sankey-chart/labels";
import { defaultSankeyChartLabels, type SankeyChartProps } from "./sankey-chart/model";
import {
  type Active,
  LABEL_GAP,
  LABEL_SIZE,
  VALUE_SIZE,
  NAME_LINE,
  VALUE_LINE,
  PAD_Y,
  type SankeyMarks,
  sankeyGeo,
} from "./sankey-chart/paint";

export {
  type SankeyNode,
  type SankeyLink,
  type SankeyAlign,
  type SankeyLayoutLink,
  type SankeyLayoutNode,
  type SankeyLayout,
  type SankeyLayoutOptions,
  layoutSankey,
  sankeyLinkPath,
} from "./sankey-chart/layout";
export { type SankeyChartLabels, defaultSankeyChartLabels, type SankeyChartProps } from "./sankey-chart/model";
export { type SankeyTableProps, SankeyTable } from "./sankey-chart/table";

// The shared flow-chart helpers moved to ./flow-utils; re-exported here for code that imported them from the sankey.
export {
  fitText,
  haloTextClass,
  markGlow,
  measureText,
  PointerFollow,
  polar,
  ribbonBlend,
  ringSector,
  roundedRectPath,
  useDarkScheme,
  useFontsLoaded,
  usePointerStore,
  type PointerStore,
  type TapState,
} from "./flow-utils";
import type { TapState } from "./flow-utils";
import { ChartFigure } from "./chart-figure";
import { ChartPatternDefs, patternFill, resolvePatterns } from "./chart-patterns";

/**
 * Flows between stages as ribbons whose thickness is the amount: where traffic comes from and
 * where it goes, a budget split, energy in and out.
 *
 * - The layout is computed here (no dependency): nodes in columns, relaxed so ribbons run as
 *   straight as possible. Ribbons fade from the source's colour into the target's.
 * - Hover or tap a node to trace every path through it; hover a ribbon to read that flow. Tap
 *   pins the readout on touch screens; a second tap activates (onNodeClick / onLinkClick).
 * - Keyboard: arrows walk the graph — up/down within a column, right/left along a node's flows
 *   and on to the next node. Values are announced; the table view (SankeyTable) lists every flow.
 * - Labels sit beside their node and are only printed where they fit, without colliding; a long
 *   name takes a second line before it is ever shortened.
 * - First view: columns grow in from left to right and ribbons draw across; data changes tween.
 *   One tween drives every mark (no per-mark animations, no React render per frame). Instant
 *   with reduced motion. A narrow card scrolls the diagram inside its own container.
 *
 * Keyboard: Tab focuses the chart; Up and Down move between the nodes of a column, Right and Left follow the flows out of and into a node, Escape clears. Enter or Space activates the node or flow being read (`onNodeClick`, `onLinkClick`).
 * Accessibility: `role="figure"` named by the chart title, with the keyboard hint as its description (`aria-describedby`, and `aria-details` to the `ChartCard` table view); focusable only when interactive; keyboard moves announce each node or flow with its values. `SankeyTable` lists every flow as the table view.
 * Glass and motion: the plot has no backdrop blur. Reduced motion draws columns and ribbons instantly.
 *
 * @example
 * ```tsx
 * import { SankeyChart } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <SankeyChart
 *       links={[
 *         { source: "Search", target: "Signup", value: 60 },
 *         { source: "Social", target: "Signup", value: 25 },
 *         { source: "Signup", target: "Paid", value: 30 },
 *         { source: "Signup", target: "Free", value: 55 },
 *       ]}
 *       aria-label="Traffic sources to plans"
 *     />
 *   );
 * }
 * ```
 *
 * @see /charts/sankey-diagram
 */
export function SankeyChart({
  links,
  nodes,
  height = 360,
  nodeWidth: nodeWidthProp = 12,
  nodePadding = 16,
  align = "justify",
  linkColor = "gradient",
  minColumnWidth = 96,
  format: formatProp,
  formatPercent: pctProp,
  locale,
  onNodeClick,
  onLinkClick,
  emptyState,
  patterns,
  labels: labelOverrides,
  "aria-label": ariaLabel,
  className,
  ref: outerRef,
  ...rest
}: ChartRoot<SankeyChartProps>) {
  const labels = { ...defaultSankeyChartLabels, ...labelOverrides };
  const format = formatProp ?? defaultCompact(locale);
  const pct = pctProp ?? defaultPercent(locale);
  const nodeWidth = clamp(nodeWidthProp, 4, 24);
  const reduced = useSheenReducedMotion();
  const rootRef = useRef<HTMLDivElement>(null);
  const rootMerged = useMergedRef(rootRef, outerRef);
  const scrollRef = useRef<HTMLDivElement>(null);
  const svgRef = useRef<SVGSVGElement>(null);
  const linkLayer = useRef<SVGGElement>(null);
  const nodeLayer = useRef<SVGGElement>(null);
  const labelLayer = useRef<SVGGElement>(null);
  const leavingLayer = useRef<SVGGElement>(null);
  const [measureRef, width] = useElementWidth<HTMLDivElement>();
  const play = useEntrance(rootRef, reduced);
  const fonts = useFontsLoaded();
  // Text tools for the current font state: a new object when the web fonts arrive, so label fits that use it are redone.
  const text = useMemo(() => ({ ready: fonts, width: measureText, fit: fitText, wrap: wrapText }), [fonts]);
  // Ordinary alpha (not multiply/screen) so ribbons stay visible on any surface, including the dark stage a light page may sit on.
  const dark = useDarkScheme();
  const blend = { opacity: dark ? 0.72 : 0.58, blend: "normal" as const };
  const [active, setActive] = useState<Active | null>(null);
  // Only keyboard moves are announced; pointer moves stay visual (no chatter while the mouse sweeps).
  const [source, setSource] = useState<"keyboard" | "pointer">("pointer");
  // Where a ribbon's tooltip is anchored while the pointer runs along it (moved without React renders).
  const tip = useFrameStore<ChartTipAnchor>();
  const boxRef = useRef<{ rect: DOMRect | null; t: number } | null>(null);
  const [scrollLeft, setScrollLeft] = useState(0);
  // The scroller's offset as last reported by its scroll events (reading it from the DOM after a render would force a layout).
  const scrollPos = useRef(0);
  const tapRef = useRef<TapState>({ id: null, wasActive: false, touch: false });
  const uid = useId();

  // Topology only (columns and values, no relaxation passes): the label margins and the empty check.
  const topology = useMemo(
    () => layoutSankey(nodes, links, { width: 400, height: 300, nodeWidth, nodePadding, align, iterations: 0 }),
    [nodes, links, nodeWidth, nodePadding, align],
  );
  const columnCount = topology.columns;

  // Wide cards print the first and last columns' labels outside the diagram; narrow ones inside.
  const outer = width >= 560 && columnCount > 1;
  const labelWidth = (n: SankeyLayoutNode) =>
    measureText(n.label, LABEL_SIZE, 500) + 6 + measureText(format(n.value), VALUE_SIZE, 400);
  const marginL = outer
    ? Math.ceil(
        Math.min(width * 0.2, Math.max(0, ...topology.nodes.filter((n) => n.column === 0).map(labelWidth)) + LABEL_GAP),
      )
    : 0;
  const marginR = outer
    ? Math.ceil(
        Math.min(
          width * 0.2,
          Math.max(0, ...topology.nodes.filter((n) => n.column === columnCount - 1).map(labelWidth)) + LABEL_GAP,
        ),
      )
    : 0;
  const needW = marginL + marginR + Math.max(0, columnCount - 1) * minColumnWidth + nodeWidth;
  const svgW = Math.max(width, needW);
  const innerW = Math.max(nodeWidth, svgW - marginL - marginR);
  const innerH = Math.max(40, height - PAD_Y * 2);

  const hasWidth = width > 0;
  const layout = useMemo(
    () =>
      hasWidth
        ? layoutSankey(nodes, links, { width: innerW, height: innerH, nodeWidth, nodePadding, align })
        : topology,
    [hasWidth, nodes, links, innerW, innerH, nodeWidth, nodePadding, align, topology],
  );
  const nodeById = useMemo(() => new Map(layout.nodes.map((n) => [n.id, n])), [layout]);
  const linkById = useMemo(() => new Map(layout.links.map((l) => [l.id, l])), [layout]);
  const columns = useMemo(() => {
    const cols: SankeyLayoutNode[][] = Array.from({ length: layout.columns }, () => []);
    for (const n of layout.nodes) cols[n.column]?.push(n);
    for (const c of cols) c.sort(byY);
    return cols;
  }, [layout]);

  const docked = useDockedReadout(width);
  const signature = useMemo(
    () => layout.links.map((l) => `${l.id}:${l.value}`).join("|") + `#${layout.nodes.map((n) => n.id).join("|")}`,
    [layout],
  );

  useScrollFade(scrollRef, svgRef, 0, svgW);

  // Validate the active mark against the current data.
  const act: Active | null =
    active && (active.kind === "node" ? nodeById.has(active.id) : linkById.has(active.id)) ? active : null;
  const actNode = act?.kind === "node" ? nodeById.get(act.id) : undefined;
  const actLink = act?.kind === "link" ? linkById.get(act.id) : undefined;

  // What lights up: every path through a node (upstream and downstream), or one flow and its ends.
  const lit = useMemo(() => {
    const litLinks = new Set<string>();
    const litNodes = new Set<string>();
    if (actNode) {
      litNodes.add(actNode.id);
      const walk = (start: SankeyLayoutNode, dir: "up" | "down") => {
        const stack = [start];
        const seen = new Set<SankeyLayoutNode>();
        while (stack.length > 0) {
          const n = stack.pop();
          if (!n) break;
          if (seen.has(n)) continue;
          seen.add(n);
          for (const l of dir === "down" ? n.sourceLinks : n.targetLinks) {
            litLinks.add(l.id);
            const next = dir === "down" ? l.target : l.source;
            litNodes.add(next.id);
            stack.push(next);
          }
        }
      };
      walk(actNode, "down");
      walk(actNode, "up");
    } else if (actLink) {
      litLinks.add(actLink.id);
      litNodes.add(actLink.source.id);
      litNodes.add(actLink.target.id);
    }
    return { links: litLinks, nodes: litNodes, any: !!actNode || !!actLink };
  }, [actNode, actLink]);

  // Readouts (tooltip rows) for nodes and links.
  const inflow = labelOverrides?.inflow ?? defaultSankeyChartLabels.inflow;
  const outflow = labelOverrides?.outflow ?? defaultSankeyChartLabels.outflow;
  const ofTotal = labelOverrides?.ofTotal ?? defaultSankeyChartLabels.ofTotal;
  const linkTitle = labelOverrides?.linkTitle ?? defaultSankeyChartLabels.linkTitle;
  const ofSource = labelOverrides?.ofSource ?? defaultSankeyChartLabels.ofSource;
  const ofTarget = labelOverrides?.ofTarget ?? defaultSankeyChartLabels.ofTarget;
  const nodeReadout = useCallback(
    (n: SankeyLayoutNode): Readout =>
      sankeyNodeReadout(n, {
        total: layout.total,
        format,
        pct,
        labels: { inflow, outflow, ofTotal, linkTitle, ofSource, ofTarget },
      }),
    [layout.total, format, pct, inflow, outflow, ofTotal, linkTitle, ofSource, ofTarget],
  );
  const linkReadout = useCallback(
    (l: SankeyLayoutLink): Readout =>
      sankeyLinkReadout(l, { format, pct, labels: { inflow, outflow, ofTotal, linkTitle, ofSource, ofTarget } }),
    [format, pct, inflow, outflow, ofTotal, linkTitle, ofSource, ofTarget],
  );

  const dock = useMemo(
    () => (docked ? dockSpace(width, [...layout.nodes.map(nodeReadout), ...layout.links.map(linkReadout)]) : 0),
    [docked, width, layout, nodeReadout, linkReadout],
  );

  // Keep the active node in view when the diagram scrolls sideways: the span to reveal, in px (NaN when nothing is active).
  const [revealX0, revealX1] = actNode
    ? [marginL + actNode.x0 - 120, marginL + actNode.x1 + 140]
    : actLink && source === "keyboard"
      ? [marginL + actLink.source.x1, marginL + actLink.target.x0]
      : [NaN, 0];
  useEffect(() => {
    const scroller = scrollRef.current;
    if (!scroller || svgW <= width || Number.isNaN(revealX0)) return;
    if (revealX0 < scroller.scrollLeft) scroller.scrollLeft = Math.max(0, revealX0);
    else if (revealX1 > scroller.scrollLeft + scroller.clientWidth)
      scroller.scrollLeft = revealX1 - scroller.clientWidth;
  }, [revealX0, revealX1, svgW, width, scrollRef]);
  const actId = act?.id;
  useLayoutEffect(() => {
    if (actId !== undefined && scrollPos.current !== scrollLeft) setScrollLeft(scrollPos.current);
  }, [actId, scrollLeft]);

  /* ---------- Labels: beside each node, only where they fit (not redone on hover) ---------- */

  const placed = useMemo(
    () => placeSankeyLabels({ layout, columns, innerW, innerH, nodeWidth, outer, marginL, marginR, format, text }),
    [layout, columns, innerW, innerH, nodeWidth, outer, marginL, marginR, format, text],
  );

  /* ---------- Layers that don't change on hover: gradients and hit areas (rendered once per layout) ---------- */

  const clickableLinks = !!onLinkClick;
  const clickableNodes = !!onNodeClick;
  const { staticLayers, handlersRef } = useSankeyStaticLayers({
    layout,
    linkColor,
    uid,
    nodeWidth,
    clickableLinks,
    clickableNodes,
  });

  // Node hatches: one per distinct node colour, in order of first use (the first colour stays solid).
  const hatchOf = useMemo(() => {
    const m = new Map<string, number>();
    for (const n of layout.nodes) if (!m.has(n.color)) m.set(n.color, m.size);
    return m;
  }, [layout]);
  const hatched = resolvePatterns(patterns, hatchOf.size);
  const nodeFill = useCallback(
    (n: SankeyLayoutNode) => patternFill(hatched, uid, hatchOf.get(n.color) ?? 0, n.color),
    [hatched, uid, hatchOf],
  );

  /* ---------- Ribbons and nodes: rendered once per layout, never restyled one by one ---------- */

  const ribbonStroke = useCallback(
    (l: SankeyLayoutLink) =>
      linkColor === "gradient"
        ? `url("#${uid}-g${l.index}")`
        : linkColor === "source"
          ? l.source.color
          : l.target.color,
    [linkColor, uid],
  );
  const markLayers = useMemo(
    () => (
      <>
        {/* Marks that left the data fade out here (filled by fadeOutLeaving, never by React). */}
        <g ref={leavingLayer} className="pointer-events-none forced-color-adjust-none" fill="none" />

        {/* Ribbons (geometry, stroke width and draw-in are painted by the tween). A reading dims the whole layer at once. */}
        <g
          ref={linkLayer}
          className="forced-color-adjust-none group-data-[dim]/sk:opacity-12 motion-ok:transition-opacity motion-ok:duration-(--sheen-duration-fast)"
          fill="none"
        >
          {layout.links.map((l) => (
            <path
              key={l.id}
              data-id={l.id}
              // Colour for the moment it fades out after leaving the data (its gradient goes with it).
              data-stroke={l.source.color}
              pathLength={1}
              stroke={ribbonStroke(l)}
              style={{ mixBlendMode: blend.blend, opacity: blend.opacity }}
              className="forced-colors:stroke-[CanvasText] forced-colors:mix-blend-normal!"
            />
          ))}
        </g>

        {/* Nodes */}
        <g
          ref={nodeLayer}
          className="forced-color-adjust-none group-data-[dim]/sk:opacity-28 motion-ok:transition-opacity motion-ok:duration-(--sheen-duration-fast)"
        >
          {layout.nodes.map((n) => (
            <path
              key={n.id}
              data-id={n.id}
              fill={nodeFill(n)}
              style={{ transformBox: "fill-box", transformOrigin: "center" }}
              className="forced-colors:stroke-[CanvasText]"
            />
          ))}
        </g>
      </>
    ),
    [layout, ribbonStroke, nodeFill, blend.blend, blend.opacity],
  );

  // The reading: the base layers dim as a whole (one attribute on their group) and the lit ribbons
  // and nodes are drawn again on top, at full strength. The copies take their shapes from the
  // marks they light up, so they follow every tween.
  const markGroup = useRef<SVGGElement>(null);
  const litLinkLayer = useRef<SVGGElement>(null);
  const litNodeLayer = useRef<SVGGElement>(null);
  const marksRef = useRef<SankeyMarks | null>(null);
  // Takes the marks as an argument (the painter passes the ones it just found), so it never closes over `marksRef`.
  const copyLit = (marks: SankeyMarks | null) => {
    const linkEls = marks?.links;
    const nodeEls = marks?.nodes;
    for (const el of Array.from(litLinkLayer.current?.children ?? []) as SVGPathElement[]) {
      const base = linkEls?.get(el.dataset.id ?? "");
      if (!base) continue;
      el.setAttribute("d", base.getAttribute("d") ?? "");
      el.setAttribute("stroke-width", base.getAttribute("stroke-width") ?? "1");
      el.style.strokeDasharray = base.style.strokeDasharray;
    }
    for (const el of Array.from(litNodeLayer.current?.children ?? []) as SVGPathElement[]) {
      const base = nodeEls?.get(el.dataset.id ?? "");
      if (!base) continue;
      el.setAttribute("d", base.getAttribute("d") ?? "");
      el.style.transform = base.style.transform;
    }
  };
  useLayoutEffect(() => copyLit(marksRef.current), [lit, markLayers]);
  const litOpacity = Math.min(0.9, blend.opacity + 0.3);
  const litLayers = lit.any && (
    <g className="pointer-events-none forced-color-adjust-none">
      <g ref={litLinkLayer} fill="none">
        {layout.links
          .filter((l) => lit.links.has(l.id))
          .map((l) => (
            <path
              key={l.id}
              data-id={l.id}
              pathLength={1}
              stroke={ribbonStroke(l)}
              style={{
                mixBlendMode: blend.blend,
                opacity: litOpacity,
                filter: actLink?.id === l.id ? markGlow(l.source.color, 8) : undefined,
              }}
              className="forced-colors:stroke-[Highlight] forced-colors:mix-blend-normal!"
            />
          ))}
      </g>
      <g ref={litNodeLayer}>
        {layout.nodes
          .filter((n) => lit.nodes.has(n.id))
          .map((n) => (
            <path
              key={n.id}
              data-id={n.id}
              fill={nodeFill(n)}
              style={{
                transformBox: "fill-box",
                transformOrigin: "center",
                filter: actNode?.id === n.id ? markGlow(n.color) : undefined,
              }}
              className="forced-colors:stroke-[CanvasText]"
            />
          ))}
      </g>
    </g>
  );

  /* ---------- Painting: one tween moves every mark, outside React ---------- */

  const geo = useMemo(() => sankeyGeo(layout, placed), [layout, placed]);
  useSankeyPaint({
    geo,
    columns: layout.columns,
    play,
    reduced,
    width,
    signature,
    nodeWidth,
    layers: { links: linkLayer, nodes: nodeLayer, labels: labelLayer, leaving: leavingLayer },
    marksRef,
    copyLit,
  });

  /* ---------- Interaction ---------- */

  function move(next: Active | null, from: "keyboard" | "pointer") {
    setSource(from);
    setActive(next);
  }

  const nearestIn = (c: number, y: number) =>
    (columns[c] ?? []).reduce<SankeyLayoutNode | null>((best, n) => {
      const d = Math.abs((n.y0 + n.y1) / 2 - y);
      return !best || d < Math.abs((best.y0 + best.y1) / 2 - y) ? n : best;
    }, null);

  function onKeyDown(event: KeyboardEvent) {
    const firstNode = columns[0]?.[0];
    let next: Active | null | undefined;
    const key = event.key;
    if (key === "Escape") {
      if (!act) return;
      next = null;
    } else if (key === "Enter" || key === " ") {
      if (actNode && onNodeClick)
        onNodeClick({ id: actNode.id, label: actNode.label, inflow: actNode.inflow, outflow: actNode.outflow });
      else if (actLink && onLinkClick)
        onLinkClick({ source: actLink.source.id, target: actLink.target.id, value: actLink.value });
      else return;
      event.preventDefault();
      return;
    } else if (key === "Home") next = firstNode ? { kind: "node", id: firstNode.id } : null;
    else if (key === "End") {
      const lastCol = columns[columns.length - 1] ?? [];
      const n = lastCol[lastCol.length - 1];
      next = n ? { kind: "node", id: n.id } : null;
    } else if (!["ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight"].includes(key)) return;
    else if (!actNode && !actLink) next = firstNode ? { kind: "node", id: firstNode.id } : null;
    else if (actNode) {
      const col = columns[actNode.column] ?? [];
      const i = col.indexOf(actNode);
      const cy = (actNode.y0 + actNode.y1) / 2;
      if (key === "ArrowDown") next = { kind: "node", id: (col[Math.min(col.length - 1, i + 1)] ?? actNode).id };
      else if (key === "ArrowUp") next = { kind: "node", id: (col[Math.max(0, i - 1)] ?? actNode).id };
      else if (key === "ArrowRight") {
        const l = actNode.sourceLinks[0];
        if (l) next = { kind: "link", id: l.id, via: "source" };
        else {
          let n: SankeyLayoutNode | null = null;
          for (let c = actNode.column + 1; c < columns.length && !n; c++) n = nearestIn(c, cy);
          next = n ? { kind: "node", id: n.id } : act;
        }
      } else {
        const l = actNode.targetLinks[0];
        if (l) next = { kind: "link", id: l.id, via: "target" };
        else {
          let n: SankeyLayoutNode | null = null;
          for (let c = actNode.column - 1; c >= 0 && !n; c--) n = nearestIn(c, cy);
          next = n ? { kind: "node", id: n.id } : act;
        }
      }
    } else if (actLink && act?.kind === "link") {
      const base = act.via === "source" ? actLink.source : actLink.target;
      const siblings = act.via === "source" ? base.sourceLinks : base.targetLinks;
      const i = siblings.indexOf(actLink);
      if (key === "ArrowDown")
        next = { kind: "link", id: (siblings[Math.min(siblings.length - 1, i + 1)] ?? actLink).id, via: act.via };
      else if (key === "ArrowUp")
        next = { kind: "link", id: (siblings[Math.max(0, i - 1)] ?? actLink).id, via: act.via };
      else if (key === "ArrowRight") next = { kind: "node", id: actLink.target.id };
      else next = { kind: "node", id: actLink.source.id };
    }
    if (next === undefined) return;
    event.preventDefault();
    move(next, "keyboard");
  }

  /** The tooltip's anchor for a pointer at (x, y) in the scroller's box: a small square under it. */
  const pointerAnchor = (x: number, y: number): ChartTipAnchor => ({ x: x - 10, y: dock + y - 10, w: 20, h: 20 });

  function onMarkPointerDown(id: string, next: Active, event: PointerEvent) {
    const same = act?.id === id;
    tapRef.current = { id, wasActive: same, touch: event.pointerType !== "mouse" };
    if (event.pointerType !== "mouse") {
      const box = scrollRef.current?.getBoundingClientRect();
      if (box) tip.set(pointerAnchor(event.clientX - box.left, event.clientY - box.top));
      move(next, "pointer");
    }
  }
  function onMarkClick(id: string, activate: () => void) {
    const t = tapRef.current;
    if (t.touch && t.id === id && !t.wasActive) return; // first tap pins the readout
    activate();
  }
  // The box is read when the pointer enters a ribbon (and a few times a second after), not on every move.
  function trackPointer(event: PointerEvent, fresh = false) {
    if (event.pointerType !== "mouse") return;
    const cached = boxRef.current;
    if (fresh || !cached || event.timeStamp - cached.t > 250)
      boxRef.current = { rect: scrollRef.current?.getBoundingClientRect() ?? null, t: event.timeStamp };
    const box = boxRef.current?.rect;
    if (box) tip.set(pointerAnchor(event.clientX - box.left, event.clientY - box.top));
  }
  const clickNode = (id: string) => {
    const n = nodeById.get(id);
    if (n && onNodeClick)
      onMarkClick(n.id, () => onNodeClick({ id: n.id, label: n.label, inflow: n.inflow, outflow: n.outflow }));
  };
  // The memoised hit layers call the latest handlers through this ref.
  useSyncRef(handlersRef, {
    enterLink: (l, e) => {
      if (e.pointerType !== "mouse") return;
      trackPointer(e, true);
      move({ kind: "link", id: l.id, via: "source" }, "pointer");
    },
    moveLink: (e) => trackPointer(e),
    leave: (e) => {
      if (e.pointerType === "mouse") setActive(null);
    },
    downLink: (l, e) => onMarkPointerDown(l.id, { kind: "link", id: l.id, via: "source" }, e),
    clickLink: (l) => {
      if (onLinkClick)
        onMarkClick(l.id, () => onLinkClick({ source: l.source.id, target: l.target.id, value: l.value }));
    },
    enterNode: (id, e) => {
      if (e.pointerType === "mouse") move({ kind: "node", id }, "pointer");
    },
    downNode: (id, e) => onMarkPointerDown(id, { kind: "node", id }, e),
    clickNode,
  });

  // Nothing to draw (declared after the last hook above so hook order never changes).
  if (layout.nodes.length === 0 || layout.links.length === 0) {
    return (
      <ChartEmpty height={height} aria-label={ariaLabel} className={className}>
        {emptyState}
      </ChartEmpty>
    );
  }

  /* ---------- Tooltip + announcement ---------- */

  let tooltip: ReactNode = null;
  let announcement = "";
  const readout = actNode ? nodeReadout(actNode) : actLink ? linkReadout(actLink) : null;
  if (readout) {
    const bounds = { w: width, h: height + dock };
    if (actNode) {
      // The node and its label: the tooltip opens beside both, never over the node's own name.
      let x0 = actNode.x0;
      let x1 = actNode.x1;
      let y0 = actNode.y0;
      let y1 = Math.max(actNode.y0 + 2, actNode.y1);
      const lb = placed.find((p) => p.id === actNode.id);
      if (lb) {
        const nameW = Math.max(...lb.name.map((line) => measureText(line, LABEL_SIZE, 500)));
        const valueW = lb.value ? measureText(lb.value, VALUE_SIZE) : 0;
        const w = lb.inline ? nameW + 6 + valueW : Math.max(nameW, valueW);
        const h = lb.name.length * NAME_LINE + (lb.value && !lb.inline ? VALUE_LINE : 0);
        x0 = Math.min(x0, lb.anchor === "start" ? lb.x : lb.x - w);
        x1 = Math.max(x1, lb.anchor === "start" ? lb.x + w : lb.x);
        y0 = Math.min(y0, lb.y - h / 2);
        y1 = Math.max(y1, lb.y + h / 2);
      }
      const anchor = { x: marginL + x0 - scrollLeft, y: dock + PAD_Y + y0, w: x1 - x0, h: y1 - y0 };
      tooltip = <FlowTip title={readout.title} rows={readout.rows} anchor={anchor} bounds={bounds} docked={docked} />;
    } else if (actLink) {
      const l = actLink;
      const mx = marginL + (l.source.x1 + l.target.x0) / 2 - scrollLeft;
      const my = PAD_Y + (l.y0 + l.y1) / 2;
      const middle = { x: mx - 4, y: dock + my - l.width / 2, w: 8, h: Math.max(4, l.width) };
      // A ribbon read with the pointer: the tooltip follows it (a transform write per frame, no render).
      tooltip = (
        <FlowTip
          title={readout.title}
          rows={readout.rows}
          anchor={middle}
          bounds={bounds}
          docked={docked}
          store={source === "pointer" ? tip : undefined}
        />
      );
    }
    const parts = readout.rows.map((r) => `${r.value} ${r.label}`.trim());
    announcement = `${readout.title}: ${parts.join(", ")}`;
    if (actNode) announcement += `. ${labels.linkCount(actNode.sourceLinks.length + actNode.targetLinks.length)}`;
  }

  return (
    <div {...rest} ref={rootMerged} className={cn("relative flex w-full min-w-0 flex-col", className)}>
      <div ref={measureRef} className="relative w-full" style={{ paddingTop: dock }}>
        {width > 0 && (
          <>
            {}
            <ChartFigure
              as="div"
              ref={scrollRef}
              // The diagram reads left to right in every writing direction: so does its scroller.
              dir="ltr"
              roleDescription={labels.roleDescription}
              label={ariaLabel}
              description={resolveInstructions(labels.instructions)}

              tabIndex={0}
              onKeyDown={onKeyDown}
              onBlur={() => setActive(null)}
              // Only a shown tooltip needs the scroll offset: scrolling with nothing read re-renders nothing.
              onScroll={(e) => {
                boxRef.current = null;
                scrollPos.current = e.currentTarget.scrollLeft;
                if (act) setScrollLeft(scrollPos.current);
              }}
              className={cn(
                "overflow-x-auto overflow-y-hidden overscroll-x-contain rounded-sheen-sm [scrollbar-width:thin]",
                chartFocusClass,
              )}
            >
              <svg
                ref={svgRef}
                aria-hidden
                // Drawn left to right in every writing direction: text anchors stay physical under dir="rtl".
                direction="ltr"
                width={svgW}
                height={height}
                className="block"
                onPointerDown={(e) => {
                  if (e.target === e.currentTarget) setActive(null);
                }}
                onPointerLeave={(e) => {
                  if (e.pointerType === "mouse") {
                    setActive(null);
                    tip.set(null);
                    boxRef.current = null;
                  }
                }}
              >
                <defs>{staticLayers.gradients}</defs>
                {hatched && (
                  <ChartPatternDefs id={uid} entries={[...hatchOf].map(([color, index]) => ({ index, color }))} />
                )}
                <g
                  ref={markGroup}
                  transform={`translate(${marginL},${PAD_Y})`}
                  data-dim={lit.any ? "" : undefined}
                  className="group/sk"
                >
                  {markLayers}
                  {litLayers}
                  <g>
                    {/* The active node gets a ring, like every other chart's active mark. */}
                    {actNode && (
                      <path
                        d={roundedRectPath(
                          actNode.x0 - 2.5,
                          actNode.y0 - 2.5,
                          nodeWidth + 5,
                          Math.max(1, actNode.y1 - actNode.y0) + 5,
                          5,
                        )}
                        fill="none"
                        strokeWidth={1.5}
                        className="pointer-events-none stroke-sheen-fg forced-colors:stroke-[Highlight]"
                      />
                    )}
                  </g>

                  {staticLayers.hits}

                  {/* Labels (never in a series colour; a halo keeps them legible over ribbons). Hovering one reads its node. */}
                  <g ref={labelLayer}>
                    {placed.map((lb) => {
                      const on = lit.nodes.has(lb.id);
                      const dim = lit.any && !on;
                      const full = nodeById.get(lb.id)?.label ?? "";
                      const nameClass = cn(
                        "font-medium",
                        dim
                          ? "fill-sheen-fg-subtle forced-colors:fill-[GrayText]"
                          : "fill-sheen-fg forced-colors:fill-[CanvasText]",
                        on && actNode?.id === lb.id && "font-semibold",
                      );
                      // Stacked lines are centred on the node: baselines from the top line down.
                      const steps = [
                        ...lb.name.map((_, i) => (i === 0 ? 0 : NAME_LINE)),
                        ...(lb.value && !lb.inline ? [VALUE_LINE] : []),
                      ];
                      const span = steps.reduce((s, v) => s + v, 0);
                      return (
                        <text
                          key={lb.id}
                          data-id={lb.id}
                          textAnchor={lb.anchor}
                          stroke="var(--sheen-chart-surface)"
                          className={cn("text-xs", haloTextClass, onNodeClick && "cursor-pointer")}
                          onPointerEnter={(e) =>
                            e.pointerType === "mouse" && move({ kind: "node", id: lb.id }, "pointer")
                          }
                          onPointerLeave={(e) => e.pointerType === "mouse" && setActive(null)}
                          onPointerDown={(e) => onMarkPointerDown(lb.id, { kind: "node", id: lb.id }, e)}
                          onClick={() => clickNode(lb.id)}
                        >
                          {lb.name.join(" ") !== full && <title>{full}</title>}
                          {lb.name.map((line, i) => (
                            <tspan key={i} x={0} dy={i === 0 ? r2(4.2 - span / 2) : NAME_LINE} className={nameClass}>
                              {line}
                            </tspan>
                          ))}
                          {lb.value &&
                            (lb.inline ? (
                              <tspan
                                dx={6}
                                className="fill-sheen-fg-muted text-2xs tabular-nums forced-colors:fill-[CanvasText]"
                              >
                                {lb.value}
                              </tspan>
                            ) : (
                              <tspan
                                x={0}
                                dy={VALUE_LINE}
                                className="fill-sheen-fg-muted text-2xs tabular-nums forced-colors:fill-[CanvasText]"
                              >
                                {lb.value}
                              </tspan>
                            ))}
                        </text>
                      );
                    })}
                  </g>
                </g>
              </svg>
            </ChartFigure>
            {tooltip ?? (docked && <ChartDockHint>{labels.hint}</ChartDockHint>)}
          </>
        )}
      </div>
      <ChartAnnouncer text={source === "keyboard" ? announcement : ""} />
    </div>
  );
}

import { type SankeyLayout, type SankeyLayoutNode } from "./layout";
import { LABEL_GAP, LABEL_SIZE, PAD_Y, VALUE_SIZE, type SankeyLabel } from "./paint";

/** The text measuring functions the label placement uses. @internal */
export type SankeyText = {
  width: (text: string, size: number, weight?: number) => number;
  fit: (text: string, room: number, size: number, weight?: number, min?: number) => string;
  wrap: (text: string, room: number, size: number, weight?: number) => string[] | null;
};

/** What the label placement depends on. @internal */
export type SankeyLabelInput = {
  layout: SankeyLayout;
  columns: SankeyLayoutNode[][];
  innerW: number;
  innerH: number;
  nodeWidth: number;
  outer: boolean;
  marginL: number;
  marginR: number;
  format: (v: number) => string;
  text: SankeyText;
};

/**
 * Labels beside each node, only where they fit: the biggest nodes claim their spot first, a label takes the
 * first of its layouts (name and value on one line, two lines, a shortened name...) that touches no other.
 * @internal
 */
export function placeSankeyLabels(o: SankeyLabelInput): SankeyLabel[] {
  const { layout, columns, innerW, innerH, nodeWidth, outer, marginL, marginR, format, text } = o;
  const placed: SankeyLabel[] = [];
  const C = columns.length;
  const gapAfter = C > 1 ? (innerW - nodeWidth) / (C - 1) - nodeWidth : innerW;
  // Every label's box so far: a new one may not touch any of them, in any column (the last
  // column's labels share their gap with the labels of the column before it).
  const boxes: { x0: number; x1: number; y0: number; y1: number }[] = [];
  const clear = (b: { x0: number; x1: number; y0: number; y1: number }) =>
    b.y0 >= -PAD_Y &&
    b.y1 <= innerH + PAD_Y &&
    !boxes.some((o) => b.x0 < o.x1 + 6 && b.x1 > o.x0 - 6 && b.y0 < o.y1 + 2 && b.y1 > o.y0 - 2);
  // Biggest nodes claim their spot first, across the whole diagram.
  const byValue = [...layout.nodes].sort((a, b) => b.value - a.value || a.index - b.index);
  for (const n of byValue) {
    const c = n.column;
    const last = c === C - 1;
    // Wide: edge columns label outwards (into the margins), the rest to the right.
    // Narrow: every column labels to the right, except the last, which labels to the left.
    const side: "start" | "end" = outer ? (c === 0 ? "end" : "start") : last ? "end" : "start";
    // Inside the diagram a label keeps clearly closer to its own node than to the facing one.
    const room =
      outer && c === 0 ? marginL - LABEL_GAP : outer && last ? marginR - LABEL_GAP : gapAfter - LABEL_GAP - 14;
    const x = side === "start" ? n.x1 + LABEL_GAP : n.x0 - LABEL_GAP;
    const cy = (n.y0 + n.y1) / 2;
    const tall = n.y1 - n.y0 >= 28;
    const value = format(n.value);
    const valueW = text.width(value, VALUE_SIZE);
    const nameW = text.width(n.label, LABEL_SIZE, 500);
    const fits = nameW <= room;
    // A name too long for one line takes two (at a space) before it is ever shortened.
    const wrapped = fits ? null : text.wrap(n.label, room, LABEL_SIZE, 500);
    const wrappedW = wrapped ? Math.max(...wrapped.map((line) => text.width(line, LABEL_SIZE, 500))) : 0;
    const fitted = fits ? n.label : text.fit(n.label, room, LABEL_SIZE, 500, 4);
    const fittedW = fitted === n.label ? nameW : text.width(fitted, LABEL_SIZE, 500);
    // Preferred first: name and value on one line; the value on a line of its own; a two-line
    // name (with its value, then without); the name alone; a shortened name. The first that
    // fits and touches nothing wins.
    type Option = { name: string[]; value: string; inline: boolean; w: number; half: number };
    const options: Option[] = [];
    if (fits && nameW + 6 + valueW <= room)
      options.push({ name: [n.label], value, inline: true, w: nameW + 6 + valueW, half: 8 });
    if (fits && tall && valueW <= room)
      options.push({ name: [n.label], value, inline: false, w: Math.max(nameW, valueW), half: 15 });
    if (wrapped?.length === 2 && valueW <= room && n.y1 - n.y0 >= 36)
      options.push({ name: wrapped, value, inline: false, w: Math.max(wrappedW, valueW), half: 22 });
    if (wrapped?.length === 2) options.push({ name: wrapped, value: "", inline: false, w: wrappedW, half: 15 });
    if (fitted && tall && valueW <= room)
      options.push({ name: [fitted], value, inline: false, w: Math.max(fittedW, valueW), half: 15 });
    if (fitted) options.push({ name: [fitted], value: "", inline: false, w: fittedW, half: 8 });
    for (const o of options) {
      const box = {
        x0: side === "start" ? x : x - o.w,
        x1: side === "start" ? x + o.w : x,
        y0: cy - o.half,
        y1: cy + o.half,
      };
      if (!clear(box)) continue;
      boxes.push(box);
      placed.push({ id: n.id, x, y: cy, anchor: side, name: o.name, value: o.value, inline: o.inline, column: c });
      break;
    }
  }
  return placed;
}

"use client";

import { useMemo, useRef } from "react";

import { cn } from "../../lib/cn";
import { r2 } from "../flow-utils";
import { sankeyLinkPath, type SankeyLayout } from "./layout";
import { LINK_GAP, type SankeyHandlers } from "./paint";

/** What the static (hover-independent) layers depend on. @internal */
export type SankeyStaticInput = {
  layout: SankeyLayout;
  linkColor: string;
  uid: string;
  nodeWidth: number;
  clickableLinks: boolean;
  clickableNodes: boolean;
};

/**
 * The layers that never change on hover, rendered once per layout: the link gradients and the hit areas
 * (ribbons at least 10px thick, then the nodes). The hit areas call the handlers kept in the returned
 * `handlersRef` at event time, so the layers never re-render when the handlers change.
 * @internal
 */
export function useSankeyStaticLayers(o: SankeyStaticInput) {
  const { layout, linkColor, uid, nodeWidth, clickableLinks, clickableNodes } = o;
  const handlersRef = useRef<SankeyHandlers | null>(null);
  const staticLayers = useMemo(() => {
    const h = () => handlersRef.current;
    // Thin flows draw on top of thick ones, so every flow can be hovered.
    const hitOrder = [...layout.links].sort((a, b) => b.width - a.width);
    return {
      gradients:
        linkColor === "gradient"
          ? layout.links.map((l) => (
              <linearGradient
                key={l.id}
                id={`${uid}-g${l.index}`}
                gradientUnits="userSpaceOnUse"
                x1={r2(l.source.x1)}
                x2={r2(l.target.x0)}
                y1={0}
                y2={0}
              >
                <stop offset="0" style={{ stopColor: l.source.color }} />
                <stop offset="1" style={{ stopColor: l.target.color }} />
              </linearGradient>
            ))
          : null,
      // Hit areas: ribbons at least 10px thick (thin ones on top), then the nodes (wider than drawn).
      hits: (
        <>
          <g fill="none" stroke="transparent">
            {hitOrder.map((l) => (
              <path
                key={l.id}
                d={sankeyLinkPath(l, LINK_GAP)}
                strokeWidth={Math.max(10, l.width)}
                className={cn(clickableLinks && "cursor-pointer")}
                onPointerEnter={(e) => h()?.enterLink(l, e)}
                onPointerMove={(e) => h()?.moveLink(e)}
                onPointerLeave={(e) => h()?.leave(e)}
                onPointerDown={(e) => h()?.downLink(l, e)}
                onClick={() => h()?.clickLink(l)}
              />
            ))}
          </g>
          <g fill="transparent">
            {layout.nodes.map((n) => (
              <rect
                key={n.id}
                x={n.x0 - 6}
                y={n.y0 - 2}
                width={nodeWidth + 12}
                height={Math.max(12, n.y1 - n.y0 + 4)}
                className={cn(clickableNodes && "cursor-pointer")}
                onPointerEnter={(e) => h()?.enterNode(n.id, e)}
                onPointerLeave={(e) => h()?.leave(e)}
                onPointerDown={(e) => h()?.downNode(n.id, e)}
                onClick={() => h()?.clickNode(n.id)}
              />
            ))}
          </g>
        </>
      ),
    };
  }, [layout, linkColor, uid, nodeWidth, clickableLinks, clickableNodes]);
  return { staticLayers, handlersRef };
}

import { KEY_SEP, num, slotColor, type ChartColor, itemAt } from "../chart-utils";
import { r2 } from "../flow-utils";

/* ======================================================================
 * Sankey layout (after d3-sankey: columns, then iterative relaxation)
 * ====================================================================== */

/** A node of a SankeyChart: an id, and optionally a label and a palette slot. */
export type SankeyNode = {
  id: string;
  /** Shown name. Default: the id. */
  label?: string;
  /**
   * Colour slot 1–8. Default: the node's position (nodes first, then any only named by a link);
   * past slot 8 a node takes the colour of its largest inflow, else neutral grey.
   */
  color?: ChartColor;
  /**
   * A status colour instead of a palette slot: "success" (a good outcome: hired, retained) or "danger" (a bad one:
   * left, cost). It uses the theme's success / danger tones, so the status colours stay in the palette's own
   * family instead of a pure green or red, and wins over `color`.
   */
  tone?: "success" | "danger";
};

/** The node fill of a status tone: deep enough in light, light enough in dark, to hold 3:1 against the chart surface. */
export const TONE_FILL = {
  success: "light-dark(var(--sheen-green-700), var(--sheen-green-400))",
  danger: "light-dark(var(--sheen-rose-700), var(--sheen-rose-400))",
} as const;

/** A flow of a SankeyChart from one node id to another, with its size. */
export type SankeyLink = {
  source: string;
  target: string;
  /** Size of the flow. Zero, negative and non-finite values are left out. */
  value: number;
};

/** How a SankeyChart places nodes across its columns: `justify`, `left`, `right` or `center`. */
export type SankeyAlign = "justify" | "left" | "right" | "center";

/**
 * A link after layout: its source and target nodes, its value, its thickness (`width`) and its
 * vertical ends in px.
 */
export type SankeyLayoutLink = {
  id: string;
  index: number;
  source: SankeyLayoutNode;
  target: SankeyLayoutNode;
  value: number;
  /** Thickness in px. */
  width: number;
  /** Centre of the ribbon where it leaves the source / enters the target. */
  y0: number;
  y1: number;
};

/**
 * A node after layout: its column, colour, inflow and outflow, its box in px and the links that enter
 * and leave it.
 */
export type SankeyLayoutNode = {
  id: string;
  label: string;
  /** Palette slot (0 = neutral). */
  slot: number;
  color: string;
  index: number;
  column: number;
  /** max(inflow, outflow). */
  value: number;
  inflow: number;
  outflow: number;
  x0: number;
  x1: number;
  y0: number;
  y1: number;
  sourceLinks: SankeyLayoutLink[];
  targetLinks: SankeyLayoutLink[];
};

/**
 * The result of laying out a Sankey: positioned nodes and links, the number of columns and the total
 * flow.
 */
export type SankeyLayout = {
  nodes: SankeyLayoutNode[];
  links: SankeyLayoutLink[];
  columns: number;
  /** Sum of every source node's outflow: the whole flow. */
  total: number;
};

/** Options of the Sankey layout: size, node width and padding, alignment and iteration count. */
export type SankeyLayoutOptions = {
  width: number;
  height: number;
  nodeWidth?: number;
  /** Smallest vertical gap between two nodes of a column (shrinks when a column is crowded). */
  nodePadding?: number;
  align?: SankeyAlign;
  /** Relaxation passes. Default 8. */
  iterations?: number;
};

/** Orders nodes by top edge, then by index. @internal */
export const byY = (a: SankeyLayoutNode, b: SankeyLayoutNode) => a.y0 - b.y0 || a.index - b.index;
const bySourceY = (a: SankeyLayoutLink, b: SankeyLayoutLink) => byY(a.source, b.source) || a.index - b.index;
const byTargetY = (a: SankeyLayoutLink, b: SankeyLayoutLink) => byY(a.target, b.target) || a.index - b.index;

/**
 * Lays out a sankey diagram in a `width` × `height` box: nodes in columns by their longest path
 * from a source, sized by their flow, then nudged up and down over a few passes so ribbons run as
 * straight as possible without nodes overlapping. Links that would close a cycle, self-links and
 * non-positive values are left out; repeated source → target pairs are summed.
 *
 * @see /charts/sankey-diagram
 */
export function layoutSankey(
  nodesIn: readonly SankeyNode[] | undefined,
  linksIn: readonly SankeyLink[],
  { width, height, nodeWidth = 12, nodePadding = 16, align = "justify", iterations = 8 }: SankeyLayoutOptions,
): SankeyLayout {
  const byId = new Map<string, SankeyLayoutNode>();
  const specs = new Map<string, SankeyNode>();
  for (const n of nodesIn ?? []) if (!specs.has(n.id)) specs.set(n.id, n);
  let order = 0;
  const node = (id: string) => {
    let n = byId.get(id);
    if (!n) {
      const spec = specs.get(id);
      n = {
        id,
        label: spec?.label ?? id,
        slot: 0,
        color: "",
        index: -1,
        column: 0,
        value: 0,
        inflow: 0,
        outflow: 0,
        x0: 0,
        x1: 0,
        y0: 0,
        y1: 0,
        sourceLinks: [],
        targetLinks: [],
      };
      byId.set(id, n);
    }
    return n;
  };
  // Indexes follow the `nodes` order first, then first mention in a link.
  const position = new Map<string, number>();
  for (const id of specs.keys()) position.set(id, order++);
  for (const l of linksIn) {
    if (!position.has(l.source)) position.set(l.source, order++);
    if (!position.has(l.target)) position.set(l.target, order++);
  }

  // Sum repeated pairs; drop self-links and non-positive values.
  const pairs = new Map<string, { source: string; target: string; value: number }>();
  for (const l of linksIn) {
    const value = num(l.value);
    if (!(value > 0) || l.source === l.target) continue;
    const key = `${l.source}${KEY_SEP}${l.target}`;
    const prev = pairs.get(key);
    if (prev) prev.value += value;
    else pairs.set(key, { source: l.source, target: l.target, value });
  }

  // Drop links that would close a cycle (back edges of a depth-first walk in input order).
  const out = new Map<string, string[]>();
  for (const p of pairs.values()) out.set(p.source, [...(out.get(p.source) ?? []), p.target]);
  const state = new Map<string, 1 | 2>();
  const back = new Set<string>();
  const ids = [...position.keys()];
  for (const start of ids) {
    if (state.has(start)) continue;
    const stack: [string, number][] = [[start, 0]];
    state.set(start, 1);
    while (stack.length > 0) {
      const top = itemAt(stack, stack.length - 1);
      const nexts = out.get(top[0]) ?? [];
      if (top[1] >= nexts.length) {
        state.set(top[0], 2);
        stack.pop();
        continue;
      }
      const next = nexts[top[1]++] ?? "";
      const s = state.get(next);
      if (s === 1) back.add(`${top[0]}${KEY_SEP}${next}`);
      else if (s === undefined) {
        state.set(next, 1);
        stack.push([next, 0]);
      }
    }
  }

  const links: SankeyLayoutLink[] = [];
  for (const [key, p] of pairs) {
    if (back.has(key)) continue;
    const s = node(p.source);
    const t = node(p.target);
    const link: SankeyLayoutLink = {
      id: key,
      index: links.length,
      source: s,
      target: t,
      value: p.value,
      width: 0,
      y0: 0,
      y1: 0,
    };
    s.sourceLinks.push(link);
    t.targetLinks.push(link);
    links.push(link);
  }
  const nodes = [...byId.values()].sort((a, b) => (position.get(a.id) ?? 0) - (position.get(b.id) ?? 0));
  nodes.forEach((n, i) => {
    n.index = i;
    n.inflow = n.targetLinks.reduce((s, l) => s + l.value, 0);
    n.outflow = n.sourceLinks.reduce((s, l) => s + l.value, 0);
    n.value = Math.max(n.inflow, n.outflow);
  });
  if (nodes.length === 0) return { nodes, links, columns: 0, total: 0 };

  // Topological order (Kahn), longest path from the sources (depth) and to the sinks (height).
  const indeg = new Map(nodes.map((n) => [n, n.targetLinks.length]));
  const queue = nodes.filter((n) => n.targetLinks.length === 0);
  const topo: SankeyLayoutNode[] = [];
  while (queue.length > 0) {
    const n = queue.shift();
    if (!n) break;
    topo.push(n);
    for (const l of n.sourceLinks) {
      const d = (indeg.get(l.target) ?? 1) - 1;
      indeg.set(l.target, d);
      if (d === 0) queue.push(l.target);
    }
  }
  const depth = new Map<SankeyLayoutNode, number>();
  for (const n of topo)
    depth.set(
      n,
      n.targetLinks.reduce((m, l) => Math.max(m, (depth.get(l.source) ?? 0) + 1), 0),
    );
  const tall = new Map<SankeyLayoutNode, number>();
  for (const n of [...topo].reverse())
    tall.set(
      n,
      n.sourceLinks.reduce((m, l) => Math.max(m, (tall.get(l.target) ?? 0) + 1), 0),
    );
  const maxDepth = Math.max(0, ...depth.values());
  for (const n of nodes) {
    const d = depth.get(n) ?? 0;
    if (align === "left") n.column = d;
    else if (align === "right") n.column = maxDepth - (tall.get(n) ?? 0);
    else if (align === "center")
      n.column =
        n.targetLinks.length > 0
          ? d
          : n.sourceLinks.length > 0
            ? Math.min(...n.sourceLinks.map((l) => depth.get(l.target) ?? 1)) - 1
            : 0;
    else n.column = n.sourceLinks.length > 0 ? d : maxDepth;
  }

  // Colours: own slot, else position (1–8), else the colour of the largest inflow, else neutral.
  for (const n of topo) {
    const spec = specs.get(n.id);
    if (spec?.color !== undefined) n.slot = spec.color;
    else if (n.index < 8) n.slot = n.index + 1;
    else {
      const main = n.targetLinks.reduce<SankeyLayoutLink | null>((m, l) => (!m || l.value > m.value ? l : m), null);
      n.slot = main?.source.slot ?? 0;
    }
    n.color = spec?.tone ? TONE_FILL[spec.tone] : slotColor(n.slot);
  }

  // Columns and horizontal positions.
  const columnCount = Math.max(...nodes.map((n) => n.column)) + 1;
  const columns: SankeyLayoutNode[][] = Array.from({ length: columnCount }, () => []);
  for (const n of nodes) itemAt(columns, n.column).push(n);
  const kx = columnCount > 1 ? (width - nodeWidth) / (columnCount - 1) : 0;
  for (const n of nodes) {
    n.x0 = columnCount > 1 ? n.column * kx : (width - nodeWidth) / 2;
    n.x1 = n.x0 + nodeWidth;
  }

  // Vertical scale: the most crowded column decides it; padding gives way before the bars do.
  const maxLen = Math.max(...columns.map((c) => c.length));
  const py = Math.max(2, Math.min(nodePadding, maxLen > 1 ? (height * 0.45) / (maxLen - 1) : nodePadding));
  const ky = Math.min(
    ...columns.map((c) => {
      const sum = c.reduce((s, n) => s + n.value, 0);
      return sum > 0 ? (height - (c.length - 1) * py) / sum : Infinity;
    }),
  );
  const k = Number.isFinite(ky) ? Math.max(0, ky) : 0;
  for (const l of links) l.width = l.value * k;
  for (const c of columns) {
    let y = 0;
    for (const n of c) {
      n.y0 = y;
      n.y1 = y + n.value * k;
      y = n.y1 + py;
    }
    // Share the free space between the nodes, so the column starts out centred.
    const free = (height - y + py) / (c.length + 1);
    c.forEach((n, i) => {
      n.y0 += free * (i + 1);
      n.y1 += free * (i + 1);
    });
    for (const n of c) {
      n.sourceLinks.sort(byTargetY);
      n.targetLinks.sort(bySourceY);
    }
  }

  const reorderNodeLinks = (n: SankeyLayoutNode) => {
    for (const { source } of n.targetLinks) source.sourceLinks.sort(byTargetY);
    for (const { target } of n.sourceLinks) target.targetLinks.sort(bySourceY);
  };
  // The y0 a target would need for the link from `source` to run straight (and vice versa).
  const targetTop = (source: SankeyLayoutNode, target: SankeyLayoutNode) => {
    let y = source.y0 - ((source.sourceLinks.length - 1) * py) / 2;
    for (const l of source.sourceLinks) {
      if (l.target === target) break;
      y += l.width + py;
    }
    for (const l of target.targetLinks) {
      if (l.source === source) break;
      y -= l.width;
    }
    return y;
  };
  const sourceTop = (source: SankeyLayoutNode, target: SankeyLayoutNode) => {
    let y = target.y0 - ((target.targetLinks.length - 1) * py) / 2;
    for (const l of target.targetLinks) {
      if (l.source === source) break;
      y += l.width + py;
    }
    for (const l of source.sourceLinks) {
      if (l.target === target) break;
      y -= l.width;
    }
    return y;
  };
  const shift = (n: SankeyLayoutNode, dy: number) => {
    n.y0 += dy;
    n.y1 += dy;
  };
  const pushDown = (c: SankeyLayoutNode[], y: number, i: number, alpha: number) => {
    for (; i < c.length; i++) {
      const n = itemAt(c, i);
      const dy = (y - n.y0) * alpha;
      if (dy > 1e-6) shift(n, dy);
      y = n.y1 + py;
    }
  };
  const pushUp = (c: SankeyLayoutNode[], y: number, i: number, alpha: number) => {
    for (; i >= 0; i--) {
      const n = itemAt(c, i);
      const dy = (n.y1 - y) * alpha;
      if (dy > 1e-6) shift(n, -dy);
      y = n.y0 - py;
    }
  };
  const resolveCollisions = (c: SankeyLayoutNode[], alpha: number) => {
    const i = c.length >> 1;
    const subject = c[i];
    if (!subject) return;
    pushUp(c, subject.y0 - py, i - 1, alpha);
    pushDown(c, subject.y1 + py, i + 1, alpha);
    pushUp(c, height, c.length - 1, alpha);
    pushDown(c, 0, 0, alpha);
  };
  for (let it = 0; it < iterations; it++) {
    const alpha = 0.99 ** it;
    const beta = Math.max(1 - alpha, (it + 1) / iterations);
    for (let ci = columnCount - 2; ci >= 0; ci--) {
      const c = itemAt(columns, ci);
      for (const source of c) {
        let y = 0;
        let w = 0;
        for (const l of source.sourceLinks) {
          const v = l.value * (l.target.column - source.column);
          y += sourceTop(source, l.target) * v;
          w += v;
        }
        if (w > 0) {
          shift(source, (y / w - source.y0) * alpha);
          reorderNodeLinks(source);
        }
      }
      c.sort(byY);
      resolveCollisions(c, beta);
    }
    for (let ci = 1; ci < columnCount; ci++) {
      const c = itemAt(columns, ci);
      for (const target of c) {
        let y = 0;
        let w = 0;
        for (const l of target.targetLinks) {
          const v = l.value * (target.column - l.source.column);
          y += targetTop(l.source, target) * v;
          w += v;
        }
        if (w > 0) {
          shift(target, (y / w - target.y0) * alpha);
          reorderNodeLinks(target);
        }
      }
      c.sort(byY);
      resolveCollisions(c, beta);
    }
  }

  for (const n of nodes) {
    let y0 = n.y0;
    let y1 = n.y0;
    for (const l of n.sourceLinks) {
      l.y0 = y0 + l.width / 2;
      y0 += l.width;
    }
    for (const l of n.targetLinks) {
      l.y1 = y1 + l.width / 2;
      y1 += l.width;
    }
  }
  const total = nodes.filter((n) => n.targetLinks.length === 0).reduce((s, n) => s + n.outflow, 0);
  return { nodes, links, columns: columnCount, total };
}

/** The ribbon of a link: a horizontal S-curve from the source's right edge to the target's left edge.
 *
 * @see /charts/sankey-diagram
 */
export function sankeyLinkPath(link: SankeyLayoutLink, gap = 2) {
  const x0 = link.source.x1 + gap;
  const x1 = link.target.x0 - gap;
  const xm = (x0 + x1) / 2;
  return `M${r2(x0)},${r2(link.y0)} C${r2(xm)},${r2(link.y0)} ${r2(xm)},${r2(link.y1)} ${r2(x1)},${r2(link.y1)}`;
}

import { type ReactNode } from "react";

import { type ChartInstructions } from "../chart-utils";
import { type SankeyNode, type SankeyLink, type SankeyAlign } from "./layout";

/* ======================================================================
 * Component
 * ====================================================================== */

/**
 * Every string SankeyChart speaks or shows, so it can be translated: pass a `Partial` as the `labels`
 * prop. Entries that need a value are functions.
 */
export type SankeyChartLabels = {
  /** Announced for the chart. */
  roleDescription: string;
  /** Appended to the accessible name: how to read it with the keyboard. */
  instructions: ChartInstructions;
  /** Shown in the readout band of a narrow chart while nothing is being read. */
  hint: string;
  /** Tooltip rows of a node. */
  inflow: string;
  outflow: string;
  ofTotal: string;
  /** Tooltip rows of a link: its share of the source's outflow / the target's inflow. */
  ofSource: (source: string) => string;
  ofTarget: (target: string) => string;
  /** Title of a link: "Source → Target". */
  linkTitle: (source: string, target: string) => string;
  /** Announced after a node's values. */
  linkCount: (count: number) => string;
};

/**
 * The built-in English strings of SankeyChart; spread it into your own `labels` and change what you
 * need. This module is a client module, so use it from client code, not from a Server Component.
 */
export const defaultSankeyChartLabels: SankeyChartLabels = {
  roleDescription: "sankey diagram",
  instructions:
    "Use the arrow keys to read it: up and down move between the nodes of a column, right and left follow the flows out of and into a node.",
  hint: "Tap a node or a flow to trace it",
  inflow: "in",
  outflow: "out",
  ofTotal: "of all flow",
  ofSource: (source) => `of ${source} outflow`,
  ofTarget: (target) => `of ${target} inflow`,
  linkTitle: (source, target) => `${source} → ${target}`,
  linkCount: (count) => `${count} ${count === 1 ? "flow" : "flows"}`,
};

/**
 * Props of SankeyChart. The component's own doc comment describes its behaviour, keyboard use and
 * accessibility.
 */
export type SankeyChartProps = {
  /** Flows between nodes. A node named only here is created with its id as the label. */
  links: readonly SankeyLink[];
  /** Names, colours and order of the nodes. Optional. */
  nodes?: readonly SankeyNode[];
  /** Sets the height of the diagram in px. Default 360. */
  height?: number;
  /** Sets the width of a node bar in px (≤ 24). Default 12. */
  nodeWidth?: number;
  /** Gap between the nodes of a column in px. Default 16. */
  nodePadding?: number;
  /**
   * Column of each node: "justify" (default: sinks go to the last column), "left" (by distance
   * from a source), "right" (by distance to a sink) or "center".
   */
  align?: SankeyAlign;
  /** Ribbon colour: a gradient from the source's colour to the target's (default), or either one. */
  linkColor?: "gradient" | "source" | "target";
  /** Narrowest space between two columns in px; a narrower card scrolls the diagram sideways. Default 96. */
  minColumnWidth?: number;
  /** Formats a flow value for the labels, tooltips and data table: takes the number, returns the text shown. Default: formatCompact in `locale`. */
  format?: (n: number) => string;
  /** Formats a share as text (0–1). Default: percentages in `locale`. */
  formatPercent?: (ratio: number) => string;
  /** Locale of the default number formats. Default "en". */
  locale?: string;
  /** Called on click / Enter on a node. */
  onNodeClick?: (node: { id: string; label: string; inflow: number; outflow: number }) => void;
  /** Called on click / Enter on a flow. */
  onLinkClick?: (link: { source: string; target: string; value: number }) => void;
  /** Shown when there is nothing to plot. */
  emptyState?: ReactNode;
  /**
   * Tell nodes apart without colour (hatch fills, one per node colour; the first colour stays solid). Ribbons keep
   * their source-to-target gradient. Default: on when the chart has more than 3 node colours.
   *
   * @default true when node colours > 3
   */
  patterns?: boolean;
  /** Override the chart's strings (i18n). */
  labels?: Partial<SankeyChartLabels>;
  /** Names the chart for assistive tech (required). */
  "aria-label": string;
  /** Adds extra classes to the outer element. */
  className?: string;
};

import { type PointerEvent } from "react";

import { duration } from "../../motion/tokens";
import { mix, r2, roundedRectPath, slice } from "../flow-utils";
import { type SankeyLayoutLink, type SankeyLayout } from "./layout";

/** The hovered or focused part: a node or a link and the end it was reached from. @internal */
export type Active = { kind: "node"; id: string } | { kind: "link"; id: string; via: "source" | "target" };
/** The pointer and focus handlers the drawn nodes and links attach. @internal */
export type SankeyHandlers = {
  enterLink: (link: SankeyLayoutLink, event: PointerEvent) => void;
  moveLink: (event: PointerEvent) => void;
  leave: (event: PointerEvent) => void;
  downLink: (link: SankeyLayoutLink, event: PointerEvent) => void;
  clickLink: (link: SankeyLayoutLink) => void;
  enterNode: (id: string, event: PointerEvent) => void;
  downNode: (id: string, event: PointerEvent) => void;
  clickNode: (id: string) => void;
};
/** A node's label: one or two lines of name, then its value (beside the name, or on its own line). */
export type SankeyLabel = {
  id: string;
  x: number;
  y: number;
  anchor: "start" | "end";
  name: string[];
  value: string;
  inline: boolean;
  column: number;
};

/** The gap between a link and its node, in pixels. @internal */
export const LINK_GAP = 2;
/** The gap between a node and its label, in pixels. @internal */
export const LABEL_GAP = 8;
/** The node name font size, in pixels. @internal */
export const LABEL_SIZE = 12;
/** The node value font size, in pixels. @internal */
export const VALUE_SIZE = 11;
/** The node name line height, in pixels. @internal */
export const NAME_LINE = 14.5;
/** The node value line height, in pixels. @internal */
export const VALUE_LINE = 14;
/** The vertical padding of the plot, in pixels. @internal */
export const PAD_Y = 10;
/** The entrance delay between columns, in seconds. @internal */
export const COLUMN_STAGGER = 0.14;

/* ---------- Geometry, painted straight to the DOM by one tween ---------- */

/** The animated geometry of one link: ends, width and colour slot. @internal */
export type LinkGeo = { x0: number; x1: number; y0: number; y1: number; w: number; c: number };
/** The animated geometry of one node. @internal */
export type NodeGeo = { x: number; y: number; h: number; c: number };
/** The animated position of one label. @internal */
export type LabelGeo = { x: number; y: number; c: number };
/** The geometry of every link, node and label, keyed by id. @internal */
export type SankeyGeo = { links: Map<string, LinkGeo>; nodes: Map<string, NodeGeo>; labels: Map<string, LabelGeo> };
/** The DOM elements of the drawn links, nodes and labels, kept for animation. @internal */
export type SankeyMarks = {
  links: Map<string, SVGPathElement>;
  nodes: Map<string, SVGPathElement>;
  labels: Map<string, SVGTextElement>;
};

/** Reduces a layout and its placed labels to the geometry that can be morphed. @internal */
export function sankeyGeo(layout: SankeyLayout, placed: SankeyLabel[]): SankeyGeo {
  return {
    links: new Map(
      layout.links.map((l) => [
        l.id,
        {
          x0: l.source.x1 + LINK_GAP,
          x1: l.target.x0 - LINK_GAP,
          y0: l.y0,
          y1: l.y1,
          w: Math.max(1, l.width),
          c: l.source.column,
        },
      ]),
    ),
    nodes: new Map(layout.nodes.map((n) => [n.id, { x: n.x0, y: n.y0, h: Math.max(1, n.y1 - n.y0), c: n.column }])),
    labels: new Map(placed.map((lb) => [lb.id, { x: lb.x, y: lb.y, c: lb.column }])),
  };
}

/** The SVG path of a link ribbon from its end geometry. @internal */
export const ribbonPath = (g: Omit<LinkGeo, "c" | "w">) => {
  const xm = (g.x0 + g.x1) / 2;
  return `M${r2(g.x0)},${r2(g.y0)} C${r2(xm)},${r2(g.y0)} ${r2(xm)},${r2(g.y1)} ${r2(g.x1)},${r2(g.y1)}`;
};

/** Interpolates two link geometries. @internal */
export const mixLink = (a: LinkGeo, b: LinkGeo, t: number): LinkGeo => ({
  x0: mix(a.x0, b.x0, t),
  x1: mix(a.x1, b.x1, t),
  y0: mix(a.y0, b.y0, t),
  y1: mix(a.y1, b.y1, t),
  w: mix(a.w, b.w, t),
  c: b.c,
});
/** Interpolates two node geometries. @internal */
export const mixNode = (a: NodeGeo, b: NodeGeo, t: number): NodeGeo => ({
  x: mix(a.x, b.x, t),
  y: mix(a.y, b.y, t),
  h: mix(a.h, b.h, t),
  c: b.c,
});
/** Interpolates two label positions. @internal */
export const mixLabel = (a: LabelGeo, b: LabelGeo, t: number): LabelGeo => ({
  x: mix(a.x, b.x, t),
  y: mix(a.y, b.y, t),
  c: b.c,
});

/** The geometry on screen part-way through a data change (an interrupted tween restarts from here). */
export function mixGeo(a: SankeyGeo, b: SankeyGeo, t: number): SankeyGeo {
  const each = <G>(to: Map<string, G>, from: Map<string, G>, f: (x: G, y: G, t: number) => G) =>
    new Map(
      [...to].map(([id, g]) => {
        const was = from.get(id);
        return [id, was ? f(was, g, t) : g] as const;
      }),
    );
  return {
    links: each(b.links, a.links, mixLink),
    nodes: each(b.nodes, a.nodes, mixNode),
    labels: each(b.labels, a.labels, mixLabel),
  };
}

/**
 * Writes every mark's geometry for one moment. `t` is the eased progress of a data change from
 * `from` to `to`; `enter` the seconds since the first-view entrance began (null: no entrance).
 * Columns grow in from left to right, ribbons draw across behind them, then the labels fade in.
 */
export function paintSankey(
  marks: SankeyMarks,
  to: SankeyGeo,
  from: SankeyGeo | null,
  t: number,
  enter: number | null,
  nodeWidth: number,
) {
  for (const [id, el] of marks.links) {
    const b = to.links.get(id);
    if (!b) continue;
    const a = from?.links.get(id);
    const g = a && t < 1 ? mixLink(a, b, t) : b;
    el.setAttribute("d", ribbonPath(g));
    el.setAttribute("stroke-width", String(r2(g.w)));
    // Drawn across with a stroke dash (the path's length is 1): on first view, and for new flows.
    const drawn = enter !== null ? slice(enter, b.c * COLUMN_STAGGER + 0.12, duration.slower) : from && !a ? t : 1;
    el.style.strokeDasharray = drawn >= 1 ? "" : `${r2(drawn * 1000) / 1000} 1`;
  }
  for (const [id, el] of marks.nodes) {
    const b = to.nodes.get(id);
    if (!b) continue;
    const a = from?.nodes.get(id);
    const g = a && t < 1 ? mixNode(a, b, t) : b;
    el.setAttribute("d", roundedRectPath(g.x, g.y, nodeWidth, g.h, 3));
    const grow = enter !== null ? slice(enter, b.c * COLUMN_STAGGER, duration.slow) : from && !a ? t : 1;
    el.style.transform = grow >= 1 ? "" : `scaleY(${r2(grow * 1000) / 1000})`;
  }
  for (const [id, el] of marks.labels) {
    const b = to.labels.get(id);
    if (!b) continue;
    const a = from?.labels.get(id);
    const g = a && t < 1 ? mixLabel(a, b, t) : b;
    el.setAttribute("transform", `translate(${r2(g.x)},${r2(g.y)})`);
    const shown = enter !== null ? slice(enter, b.c * COLUMN_STAGGER + 0.25, duration.base) : from && !a ? t : 1;
    el.style.opacity = shown >= 1 ? "" : String(r2(shown));
  }
}

import type { Readout } from "../chart-fit";
import type { SankeyLayoutLink, SankeyLayoutNode } from "./layout";
import type { SankeyChartLabels } from "./model";

/** The strings and formatters a Sankey readout is made of. @internal */
export type SankeyReadoutInput = {
  format: (v: number) => string;
  pct: (v: number) => string;
  labels: Pick<SankeyChartLabels, "inflow" | "outflow" | "ofTotal" | "linkTitle" | "ofSource" | "ofTarget">;
};

/** The tooltip rows of one node: its inflow, outflow and share of the diagram total. @internal */
export function sankeyNodeReadout(n: SankeyLayoutNode, o: SankeyReadoutInput & { total: number }): Readout {
  const { total, format, pct, labels } = o;
  const rows = [];
  if (n.targetLinks.length > 0)
    rows.push({ label: labels.inflow, value: format(n.inflow), color: n.color, kind: "rect" as const });
  if (n.sourceLinks.length > 0)
    rows.push({
      label: labels.outflow,
      value: format(n.outflow),
      color: n.targetLinks.length > 0 ? "transparent" : n.color,
      kind: "rect" as const,
    });
  if (total > 0)
    rows.push({
      label: labels.ofTotal,
      value: pct(n.value / total),
      color: "transparent",
      kind: "rect" as const,
    });
  return { title: n.label, rows };
}

/** The tooltip rows of one link: its value and its share of the source's outflow and the target's inflow. @internal */
export function sankeyLinkReadout(l: SankeyLayoutLink, o: SankeyReadoutInput): Readout {
  const { format, pct, labels } = o;
  return {
    title: labels.linkTitle(l.source.label, l.target.label),
    rows: [
      { label: "", value: format(l.value), color: l.source.color, kind: "rect" },
      {
        label: labels.ofSource(l.source.label),
        value: pct(l.source.outflow > 0 ? l.value / l.source.outflow : NaN),
        color: "transparent",
        kind: "rect",
      },
      {
        label: labels.ofTarget(l.target.label),
        value: pct(l.target.inflow > 0 ? l.value / l.target.inflow : NaN),
        color: "transparent",
        kind: "rect",
      },
    ],
  };
}

import { type ReactNode } from "react";

import { ChartValueTable, defaultCompact, defaultPercent } from "../heatmap";
import { type SankeyNode, type SankeyLink, layoutSankey } from "./layout";

/* ---------- Table view ---------- */

/**
 * Props of SankeyTable, the table view of the chart: the chart's data and formatting props plus a
 * hidden `caption` for screen readers.
 */
export type SankeyTableProps = {
  /** The same flows as the chart: { source, target, value }. */
  links: readonly SankeyLink[];
  /** Optional node labels and colours, as in the chart. */
  nodes?: readonly SankeyNode[];
  /** Formats a flow value for the table cells: takes the number, returns the text shown. Default compact numbers in `locale`. */
  format?: (n: number) => string;
  /** Formats a share of the total for the table cells: takes the share, returns the text shown. Default percentages in `locale`. */
  formatPercent?: (ratio: number) => string;
  /** Locale of the default number formats. Default "en". */
  locale?: string;
  /** Hidden caption that names the table for screen readers. */
  caption?: string;
  /** Override the column headers: { source, target, value, ofSource, ofTarget }. */
  headers?: Partial<{ source: string; target: string; value: string; ofSource: string; ofTarget: string }>;
  /** Shown when there are no flows. */
  emptyState?: ReactNode;
};

/**
 * Every flow of a sankey as a table: from, to, amount, and its share of each end.
 *
 * Takes the chart's `links`, `nodes`, `format`, `formatPercent` and `locale`, plus `caption` (hidden, names the table), `headers` ({ source, target, value, ofSource, ofTarget }) and `emptyState`. A real table: every flow with its amount and share of each end. Static (no motion). Pass it to `ChartCard table`.
 *
 * @example
 * ```tsx
 * import { SankeyTable } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <SankeyTable links={[{ source: "Search", target: "Signup", value: 60 }, { source: "Signup", target: "Paid", value: 30 }]} caption="Traffic sources to plans" />
 *   );
 * }
 * ```
 *
 * @see /charts/sankey-diagram
 */
export function SankeyTable({
  links,
  nodes,
  format: formatProp,
  formatPercent: pctProp,
  locale,
  caption,
  headers,
  emptyState,
}: SankeyTableProps) {
  const format = formatProp ?? defaultCompact(locale);
  const pct = pctProp ?? defaultPercent(locale);
  const h = {
    source: "From",
    target: "To",
    value: "Value",
    ofSource: "% of source",
    ofTarget: "% of target",
    ...headers,
  };
  const layout = layoutSankey(nodes, links, { width: 100, height: 100 });
  const ordered = [...layout.links].sort(
    (a, b) => a.source.column - b.source.column || a.source.index - b.source.index || b.value - a.value,
  );
  return (
    <ChartValueTable
      caption={caption}
      emptyState={emptyState}
      columns={[
        { label: h.source },
        { label: h.target, align: "start" },
        { label: h.value },
        { label: h.ofSource },
        { label: h.ofTarget },
      ]}
      rows={ordered.map((l) => [
        l.source.label,
        <span className="text-sheen-fg-muted">{l.target.label}</span>,
        format(l.value),
        pct(l.source.outflow > 0 ? l.value / l.source.outflow : NaN),
        pct(l.target.inflow > 0 ? l.value / l.target.inflow : NaN),
      ])}
    />
  );
}

"use client";

import { useLayoutEffect, useRef, type RefObject } from "react";
import { animate } from "motion/react";

import { useSyncRef } from "../../hooks/use-latest";
import { duration } from "../../motion/tokens";
import { changeCurve, fadeOutLeaving, marksById } from "../flow-utils";
import { COLUMN_STAGGER, mixGeo, paintSankey, type SankeyGeo, type SankeyMarks } from "./paint";

/**
 * Paints the sankey outside React: one tween moves every mark. The first view sweeps the columns in, a data
 * change tweens from where the marks are (an interrupted change restarts from the geometry it reached), a
 * resize applies at once, and reduced motion draws the final frame.
 * @internal
 */
export function useSankeyPaint({
  geo,
  columns,
  play,
  reduced,
  width,
  signature,
  nodeWidth,
  layers,
  marksRef,
  copyLit,
}: {
  geo: SankeyGeo;
  columns: number;
  play: boolean;
  reduced: boolean;
  width: number;
  /** Changes when the data changes, not when the size does. */
  signature: string;
  nodeWidth: number;
  layers: {
    links: RefObject<SVGGElement | null>;
    nodes: RefObject<SVGGElement | null>;
    labels: RefObject<SVGGElement | null>;
    leaving: RefObject<SVGGElement | null>;
  };
  /** Receives the marks it just found, so the lit copies follow every frame. */
  marksRef: RefObject<SankeyMarks | null>;
  copyLit: (marks: SankeyMarks | null) => void;
}) {
  const lastSignature = useRef(signature);
  const shownRef = useRef<SankeyGeo | null>(null);
  // The running tween, and the geometry it has reached (an interrupted change restarts from there).
  const runRef = useRef<{ now: () => SankeyGeo } | null>(null);
  // When the first-view entrance began (performance.now()), or -Infinity once it can't run any more.
  const enterAt = useRef<number | null>(null);
  const nodeWidthRef = useRef(nodeWidth);
  useSyncRef(nodeWidthRef, nodeWidth);
  const copyLitRef = useRef(copyLit);
  useSyncRef(copyLitRef, copyLit);

  useLayoutEffect(() => {
    if (width === 0) return;
    // Data changes tween; a resize (same signature, new geometry) applies at once.
    const dataChanged = lastSignature.current !== signature;
    lastSignature.current = signature;
    const prev = marksRef.current;
    const marks: SankeyMarks = {
      links: marksById(layers.links.current),
      nodes: marksById(layers.nodes.current),
      labels: marksById(layers.labels.current),
    };
    marksRef.current = marks;
    const from = runRef.current?.now() ?? shownRef.current;
    runRef.current = null;
    shownRef.current = geo;
    const paint = (t: number, enter: number | null, base: SankeyGeo | null = null) => {
      paintSankey(marks, geo, base, t, enter, nodeWidthRef.current);
      copyLitRef.current(marks);
    };
    if (reduced) {
      enterAt.current ??= -Infinity;
      paint(1, null);
      return;
    }
    if (!play) {
      paint(1, 0); // waiting for the first view: in place, not grown or drawn yet
      return;
    }
    const total = Math.max(0, columns - 1) * COLUMN_STAGGER + 0.25 + duration.slower;
    enterAt.current ??= performance.now();
    const elapsed = (performance.now() - enterAt.current) / 1000;
    if (elapsed < total) {
      // First view (or new data while it runs): carry on from where the entrance is.
      paint(1, elapsed);
      const controls = animate(elapsed, total, {
        duration: total - elapsed,
        ease: "linear",
        onUpdate: (e) => paint(1, e),
      });
      return () => controls.stop();
    }
    // Marks that left the data fade out where they were.
    if (prev)
      fadeOutLeaving(layers.leaving.current, [...prev.links.values(), ...prev.nodes.values(), ...prev.labels.values()]);
    if (!dataChanged || !from) {
      paint(1, null); // a resize: straight to the new geometry
      return;
    }
    let t = 0;
    paint(0, null, from);
    const controls = animate(0, 1, {
      duration: duration.slow,
      ease: "linear",
      onUpdate: (k) => {
        t = changeCurve(k);
        paint(t, null, from);
      },
      onComplete: () => {
        runRef.current = null;
      },
    });
    runRef.current = { now: () => (t >= 1 ? geo : mixGeo(from, geo, t)) };
    return () => controls.stop();
    // eslint-disable-next-line react-hooks/exhaustive-deps -- `layers` is a bag of refs; the rest is read through refs.
  }, [geo, play, reduced, width, signature, columns]);
}

